/**
 * Design token accessors.
 *
 * The single source of truth is `design-system/letxnepal/tokens.json`, generated by the
 * ui-ux-pro-max skill. This module is the typed, programmatic view of that file so
 * tests and server code can assert token integrity without scraping CSS.
 *
 * Note: the generator's font recommendation (Noto Sans Thai) was overridden to a
 * Devanagari-capable family. See docs/provenance.md.
 */
import tokens from "../../design-system/letxnepal/tokens.json";

export type TokenColor = { $value: string; $type: "color" };
export type TokenGroup = Record<string, TokenColor>;

const colorGroup = (tokens.color ?? {}) as TokenGroup;

/** Flat map of semantic colour name -> hex value. */
export const colors: Record<string, string> = Object.fromEntries(
  Object.entries(colorGroup).map(([name, token]) => [name, token.$value]),
);

const fontGroup = (tokens.font ?? {}) as Record<string, { $value: string; $type: string }>;

export const fonts: Record<string, string> = Object.fromEntries(
  Object.entries(fontGroup).map(([name, token]) => [name, token.$value]),
);

const spaceGroup = (tokens.space ?? {}) as Record<string, { $value: string; $type: string }>;

export const spacing: Record<string, string> = Object.fromEntries(
  Object.entries(spaceGroup).map(([name, token]) => [name, token.$value]),
);

/** Semantic colour pairs that must satisfy WCAG AA. */
export const contrastPairs = [
  { name: "foreground on background", foreground: colors.foreground, background: colors.background },
  { name: "foreground on card", foreground: colors["card-foreground"], background: colors.card },
  { name: "muted-foreground on muted", foreground: colors["muted-foreground"], background: colors.muted },
  { name: "muted-foreground on background", foreground: colors["muted-foreground"], background: colors.background },
  { name: "on-primary on primary", foreground: colors["on-primary"], background: colors.primary },
  { name: "on-accent on accent", foreground: colors["on-accent"], background: colors.accent },
  { name: "on-destructive on destructive", foreground: colors["on-destructive"], background: colors.destructive },
] as const;

/** Product palette name, recorded for provenance and tests. */
export const designSystem = {
  name: "letxNepal",
  generatedBy: "ui-ux-pro-max",
  style: "Aurora UI",
  motion: 2,
  primary: colors.primary,
  accent: colors.accent,
  headingFont: fonts.heading,
  bodyFont: fonts.body,
} as const;
